
const form=document.getElementById('contact-form'),send=document.getElementById('send'),edit=document.getElementById('edit');let confirming=false;
form.addEventListener('submit',e=>{if(!confirming){e.preventDefault();const summary=document.getElementById('summary');summary.replaceChildren();for(const [id,label] of [['name','お名前'],['email','メールアドレス'],['category','お問い合わせの種類'],['message','お問い合わせ内容']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=document.getElementById(id).value;summary.append(dt,dd)}document.getElementById('input-panel').hidden=true;document.getElementById('confirm-panel').hidden=false;edit.hidden=false;send.textContent='この内容で送信する →';confirming=true;document.getElementById('confirm-heading').focus()}else{send.disabled=true;send.textContent='送信画面へ移動中…'}});
edit.addEventListener('click',()=>{confirming=false;document.getElementById('input-panel').hidden=false;document.getElementById('confirm-panel').hidden=true;edit.hidden=true;send.textContent='入力内容を確認する →';document.getElementById('name').focus()});window.addEventListener('pageshow',()=>{send.disabled=false;send.textContent=confirming?'この内容で送信する →':'入力内容を確認する →'});
